Here is a Python function for implementing the Breadth-First Search (BFS) algorithm to find a path in a graph:

```python
from collections import deque

def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    queue = deque([(start, [start])])  # Queue to keep track of nodes to explore
    visited = set()  # Set to keep track of visited nodes

    while queue:
        (current, path) = queue.popleft()  # Get the next node to explore

        if current == goal:
            return path  # Return the path if current node is the goal

        if current not in visited:
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))  # Add neighbors to the queue

    return None  # Return None if goal is unreachable
